INSERT INTO series(series_id, slug, name, network, start_date, end_date) VALUES (1,'cbsrmt','CBS Radio Mystery Theater','CBS','1974-01-06','1982-12-31') ON CONFLICT (series_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (1,'eheckart','Eileen',NULL,'Heckart','Eileen Heckart','Basically she was quite plain looking, but her tall stature and dominant, harsh voice were among her strong attributes and she was adept at playing the acerbic, stern, driven woman but she was also quite versatile in her characterizations. She claimed her smoky voice was a result of a bout with whooping cough during her college years.','1905-04-02','1905-06-23','https://www.imdb.com/name/nm0373012/','CBSRMT',1) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (2,'hslesar','Henry',NULL,'Slesar','Henry Slesar','Advertising executive who started the Slesar & Kanzer advertising agency. In the 50s and 60s was head writer of the daytime soap The Edge of Night. Wrote 24 episodes of Alfred Hitchcock Presents.','1905-04-10','1905-06-24','https://www.imdb.com/name/nm0805748/','CBSRMT',2) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (3,'amoorehead','Agnes',NULL,'Moorehead','Agnes Moorehead',NULL,'1900-12-06','1974-04-30','https://www.imdb.com/name/nm0001547/','CBSRMT',3) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (4,'sortega','Santos',NULL,'Ortega','Santos Ortega','Ortega was a voice-over regular on the popular 1930s radio series Gangbusters that featured weekly episodes based actual crime incidents. Each program ended with various descriptions of wanted criminals, many of whom were later arrested due to avid listener participation. Ortega was an original cast member of the CBS daytime drama "As The World Turns" playing Will "Grandpa" Hughes from 1956-76.)','1899-06-30','1976-04-10','https://www.imdb.com/name/nm0650948/','CBSRMT',4) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (5,'wredfield','William',NULL,'Redfield','William Redfield','The son of a Manhattan orchestra conductor and a former Ziegfeld Follies girl, little Billy Redfield made his Broadway bow at age 9 in Swing Your Lady. Billy launched his radio career around the same time, and made his earliest movie appearance in 1939. As adult actor William Redfield, he was one of the original founders of the influential Actors Studio. While his film assignments of the 1950s and 1960s were unremarkable (as Captain Owens in 1966''s Fantastic Voyage, for example, he played third fiddle to the special effects and Raquel Welch''s diving suit), he remained a much-in-demand stage performer, and also proved a delightful raconteur on such TV chatfests as The Tonight Show.','1927-01-26','1976-08-17','https://www.imdb.com/name/nm0714835/','CBSRMT',5) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (6,'areed','Alan',NULL,'Reed','Alan Reed','Veteran radio actor supplied the voice of TV cartoon character "Fred Flintstone."  Created the phrase ''Yabba Dabba Doo'' for The Flintstones.  Before portraying Pasquale on "Life with Luigi" (1952) on television, he originated the character on CBS Radio (1948-1953).','1907-08-20','1977-06-14','https://www.imdb.com/name/nm0715284/','CBSRMT',6) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (7,'pmcgrath','Paul',NULL,'McGrath','Paul McGrath','McGrath was a well known radio actor during the period between 1943 and 1954. He appeared as a character named John Wayne in the radio soap entitled BIG SISTER.  Portrayed the second Raymond, the host of CBS and ABC Radio''s "The Inner Sanctum" (1945-1952).','1904-04-11','1978-04-13','https://www.imdb.com/name/nm0569864/','CBSRMT',7) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (8,'bmorrison','Bret',NULL,'Morrison','Bret Morrison','Was the last person that portrayed "The Shadow" on the radio.','1912-05-05','1978-09-25',NULL,'CBSRMT',8) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (9,'scotsworth','Staats',NULL,'Cotsworth','Staats Cotsworth','He was the lead character of CBS Radio''s "Casey, Crime Photographer" (1943-1955). The show''s named changed through the years (07/07/43 to 04/01/44 Flashgun Casey, 04/08/44 to 06/26/45 Casey, Press Photographer, 07/11/45 to 03/13/47 Crime Photographe','1908-02-17','1979-04-09','https://www.imdb.com/name/nm0182901/','CBSRMT',9) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (10,'ljanney','Leon',NULL,'Janney','Leon Janney','The son of a stage actress.. Leon Janney (born Laon Ramon) had been in vaudeville before entering films at the age of 11, in 1928...  He turned to radio... and would become one of that medium''s more prolific performers in the decades to come. Accepting the occasional screen role, Janney later appeared on such television soap operas as Another World and Edge of Night.','1917-04-01','1980-10-28','https://www.imdb.com/name/nm0417824/','CBSRMT',10) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (11,'npolen','Nat',NULL,'Polen','Nat Polen','Nat Polen was a star on "Indictment" which aired Sunday Afternoons on the CBS Radio Network back in the late 1950s. Polen broke into daytime television back in the 50''s and he was one of the original cast members on both soap operas. He played Dr. Doug Cassen on the CBS daytime drama "As The World Turns" from 1956-67 and as Dr. Jim Craig on the ABC daytime drama "One Life to Live" from 1968-81.','1914-06-14','1981-05-03','https://www.imdb.com/name/nm0688960/','CBSRMT',11) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (12,'imartin','Ian',NULL,'Martin','Ian Martin',NULL,'1912-04-29','1981-07-30',NULL,'CBSRMT',12) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (13,'hconried','Hans',NULL,'Conried','Hans Conried','Hans Conried was born in Baltimore, raised both there and in New York City. He studied acting at Columbia University, and played many major classical roles onstage. After having been a member of Orson Welles'' Mercury Theatre Company, he was heard as Professor Kropotkin on the radio show "My Friend Irma" and had various roles on the "Edgar Bergen - Charlie McCarthy Show". He was in the original cast of Cole Porter''s 1953 Broadway hit "Can-Can" and stayed with the show for more than a year. Known for his sharp wit, Conried was in demand as an actor, panelist and narrator, appearing frequently in television series and movies throughout the 60s and 70s. Best known for providing the voice of Snidely Whiplash in the cartoon "Dudley Doo-Right." Conried had a 13-year run as Uncle Tonoose on the "Make Room for Daddy" TV show from 1958 to 1971','1917-04-15','1982-01-05','https://www.imdb.com/name/nm0175788/','CBSRMT',13) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (14,'hmarlowe','Hugh',NULL,'Marlowe','Hugh Marlowe',' Marlowe was born Hugh Hipple in Philadelphia, and began his stage career in the 1930s at the Pasadena Playhouse in California. He performed extensively on radio, stage, television and film with credits including off-Broadway productions of "The Deer Park" in 1967 and "All My Sons" in 1974. Hugh married CBSRMT alum K.T. Stevens from 1946-1968 and he also played the fourth Jim Matthews on the NBC daytime drama "Another World" from 1969-1982.','1911-01-30','1982-05-02','https://www.imdb.com/name/nm0549280/','CBSRMT',14) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (15,'sstrudwick','Shepperd',NULL,'Strudwick','Shepperd Strudwick',' Longtime soap opera actor Strudwick appear on four daytime dramas. He played Dr. Field on As The World Turns from 1961-65, the third Jim Matthews on Another World from 1964-69, and he played the second Victor Lord on One Life to Live from 1974-76.','1907-09-22','1983-01-15','https://www.imdb.com/name/nm0791805/','CBSRMT',15) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (16,'mkellin','Mike',NULL,'Kellin','Mike Kellin',NULL,'1922-04-26','1983-08-26',NULL,'CBSRMT',16) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (17,'ascourby','Alexander',NULL,'Scourby','Alexander Scourby','AS may be best known for his famous narration of the King James Bible. <P>"The precise, mellifluous voice of Alexander Scourby, trained in Shakespearean roles in the 1930''s and perfected in radio dramatic parts in the 1940''s, has become a well-known sound on Broadway, in motion pictures, and on television, where as Harriet Van Horne has observed, he is "the most sensitive and knowing narrator in the business."','1913-11-13','1985-02-22',NULL,'CBSRMT',17) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (18,'mhigby','Mary','Jane','Higby','Mary Jane Higby',NULL,'1915-06-29','1986-02-01',NULL,'CBSRMT',18) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (19,'hdasilva','Howard',NULL,'Da Silva','Howard Da Silva','Howard da Silva was one of over 324 actors, writers and directors who fell victim to the Hollywood blacklisting of the early 1950''s, and had his career effectively ruined. He originally was a steelworker before making his debut, at the age of 20 in ','1909-05-04','1986-02-16',NULL,'CBSRMT',19) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (20,'ltuttle','Lurene',NULL,'Tuttle','Lurene Tuttle','Voice of Effie Perrine on radio''s Adventures of Sam Spade (1946-1951).','1906-08-29','1986-05-28',NULL,'CBSRMT',20) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (21,'vgregg','Virginia',NULL,'Gregg','Virginia Gregg','Virginia Gregg was one of the busiest radio actors in the business. Regular appearances on such radio shows as Dragnet, Nightbeat, The Lone Ranger and many more. Had extremely wide range, playing any female character. Was radio''s female equivalent to William Conrad, Ben Wright, and Elliott Lewis. She portrayed Miss Wong on CBS Radio''s "Have Gun, Will Travel" (1958-1960). Gregg was the second actress to play Claire "Brooksie" Brooks on Mutual Radio''s "Let George Do It" (1949-1954) and also portrayed Helen Asher on NBC (1949-1952) and CBS (1952-1953 Radio''s "Richard Diamond, Private Detective. Gregg also provided the voice of the mother in Psycho (1960).','1916-03-06','1986-09-15',NULL,'CBSRMT',21) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (22,'ahewitt','Alan',NULL,'Hewitt','Alan Hewitt','Serious, firm-jawed American support actor on Broadway from the 30s through the 50s who later entered films and TV, an unsympathaetic comic foil in 60s Disney''s film fluff. His best known role was as the ever-suspicious Detective Brennan on the sitcom My Favorite Martian','1915-01-21','1986-11-07',NULL,'CBSRMT',22) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (23,'rdekoven','Roger',NULL,'DeKoven','Roger DeKoven','A character actor, known for English and European stage plays, however, little is known about his screen roles. Roger De Koven has also acted in Broadway plays and stage plays in America, he is best known for spending 20 years in the soap opera _"Days of our Lives" (1961)_ and also co-starred in Oliver Stone''s 1974 film Seizure (1974). After co-starring with Robin Williams in Seize the Day (1986) in 1986, De Koven died of natural causes at the tender age of 80.','1907-10-22','1988-01-28',NULL,'CBSRMT',23) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (24,'ejuster','Evie',NULL,'Juster','Evie Juster',NULL,'1915-01-24','1988-06-19',NULL,'CBSRMT',24) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (25,'aseymour','Anne',NULL,'Seymour','Anne Seymour',NULL,'1909-09-11','1988-12-08',NULL,'CBSRMT',25) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (26,'mkramer','Mandel',NULL,'Kramer','Mandel Kramer','In addition to acting in many RMT shows, MK also starred in X-1 shows (like the interesting <em>A Logic Named Joe</em>).  MK was the second Johhny Dollar.  He also appeared on Edge of Night with RMT alum Teri Keane.','1916-03-12','1989-01-29','https://www.imdb.com/name/nm0469608/','CBSRMT',26) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (27,'jsilver','Joe',NULL,'Silver','Joe Silver','Mr. Silver was the second and the last host/performer to play "Capt. Jet" on The WCBS TV Ch. 2 NYC version of "Space Funnies" / "Capt. Jet", on Saturday and Sunday mornings from Saturday and Sunday June 19, and 20, 1955 to Saturday and Sunday December 30 and 31, 1960. The first host/performer to play "Capt. Jet" was actor and radio DJ Stan Sawyer. Mr. Sawyer MC''d the program from Saturday and Sunday July 5 and 6, 1953 to Saturday and Sunday June 28 and 29, 1955.','1922-09-28','1989-02-27','https://www.imdb.com/name/nm0798718/','CBSRMT',27) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (28,'amoss','Arnold',NULL,'Moss','Arnold Moss','Another of the unsung character actors we see, we recognize but don''t know the name, he was a gem of an actor best suited for villainy. He was another of the aristocratic types who were most often cast in such roles as dukes, earls, counts and the like. He was a Shakespearean actor and they most often seem to fit that mold. It is very difficult to believe he was a New Yorker and not of British descent. Of medium height and build with a stern looking face, baggy, lived-in eyes and one of the most charming resonant, bass voices in all of show business he created many memorable roles.  (dougmacauley.com) <P>Note that AM adapted or wrote some RMT stories.','1910-01-28','1989-12-15','https://www.imdb.com/name/nm0608909/','CBSRMT',28) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (29,'bkroeger','Berry',NULL,'Kroeger','Berry Kroeger',NULL,'1912-10-16','1991-01-04','https://www.imdb.com/name/nm0471854/','CBSRMT',29) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (30,'lkrugman','Lou',NULL,'Krugman','Lou Krugman',NULL,'1914-07-19','1992-08-08','https://www.imdb.com/name/nm0472632/','CBSRMT',30) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (31,'fgwynne','Fred',NULL,'Gwynne','Fred Gwynne','Fred Gwynne was that great baritone that soothed or scared us in so many RMT shows.  His voice is distinctive; once you''ve heard it you can always identify him in the other shows. <P>Fred was a Harvard grad, but is best known for his role as Herman Munster:  "Funny thing, yesterday morning I found my youngest son and daughter watching the rerun of  an old episode and I said, ''My God, THAT''S not still on, is it?'' Well, even so, I was very lucky and it was great fun to be as much of a household product as something like Rinso. I almost wish I could do it all over again."','1926-07-10','1993-07-02','https://www.imdb.com/name/nm0001304/','CBSRMT',31) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (32,'caidman','Charles',NULL,'Aidman','Charles Aidman','Actor, author, director and composer, educated at the University of Indiana and the Neighborhood Playhouse. His New York off-Broadway stage work inluded parts in Career", "The Cretan Woman", and others. He conceived, directed and acted in "Spoon River Anthology". Joining ASCAP in 1963, he collaborated with Naomi Caryl Hirshhorn in the songs "Spoon River" and "I Am, I Am". " (imdb.org)','1925-01-21','1993-11-07','https://www.imdb.com/name/nm0014493/','CBSRMT',32) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (33,'ptrueman','Paula',NULL,'Trueman','Paula Trueman','A character actress of stage and screen, Paula Trueman first appeared in Broadway revues during the 1920s. Proving herself to be a versatile performer, at home in dramas, comedies, and musicals, Trueman made her first feature film appearance in Crime Without Passion (1934). Her film career lasted until the mid-''80s and was as diverse as her stage work. (Sandra Brennan, All Movie Guide)  ','1900-04-25','1994-03-23','https://www.imdb.com/name/nm0874119/','CBSRMT',33) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (34,'gsorel','Guy',NULL,'Sorel','Guy Sorel',NULL,'1914-08-12','1994-04-05',NULL,'CBSRMT',34) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (35,'swalker','Sydney',NULL,'Walker','Sydney Walker',NULL,'1921-05-05','1994-09-30','https://www.imdb.com/name/nm0908246/','CBSRMT',35) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (36,'cmatthews','Carmen',NULL,'Matthews','Carmen Matthews','Her film credits include ''Butterfield 8, '' ''Rage to Live, '' ''Sounder, '' and ''Daniel.'' She also appeared in several TV movies and is still seen in reruns as Col. Lillian Rayborn in an episode of the TV series ''M.A.S.H.'' Miss Matthews had teamed on the Broadway stage with such actors as Don Ameche Angela Lansbury and Joanne Woodward. Her last role was in ''The Best Year of My Life, '' a 1990 television movie with Mary Tyler Moore and Bernadette Peters.','1914-05-08','1995-08-31','https://www.imdb.com/name/nm0558618/','CBSRMT',36) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (37,'wprince','William',NULL,'Prince','William Prince','William was a character actor whose popularity was due to hundreds of appearances in soap operas. Going from the stage to the screen, William had an undistinquished movie career in the 40''s which ran out of steam after about four years. But in the 50''s, he would find his calling on the small screen. On "Young Dr. Malone", he played the father for five years. He was also cast in "Another World", "The Edge of Night", "Search for Tomorrow" and "A World Apart". One note worthy credit was that he was part of the continuing cast on the first hour long Television drama series "The Mask (1954)". By the 70''s and 80''s he appeared in a number of Television Mini-Series and Television Movies. On the stage, he appeared in plays by Eugene O''Neill and Edward Albee.<P> He was married to <a href=http://www.mousetrap.net/~mouse/cbsrmt/showperson.php?id=adabney>Augusta Dabney</a>. ','1913-01-26','1996-10-08','https://www.imdb.com/name/nm0697733/','CBSRMT',37) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (38,'waddy','Wesley',NULL,'Addy','Wesley Addy','Addy was an original cast member for the ABC daytime drama Loving from 1983-91 and was married to Oscar-winning actress and CBSRMT alum Celeste Holm.','1913-08-04','1996-12-31','https://www.imdb.com/name/nm0011741/','CBSRMT',38) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (39,'gpetrie','George',NULL,'Petrie','George Petrie','With his warm resonant voice, superb timing, and innate charm, George O. Petrie began his career on the stage with a background on Broadway and years in summer stock. After his service in World War II, he made his final appearance on Broadway in Brighten the Corner," and then began a busy career in network radio which included the title roles in "The Amazing Mr. Malone," "The Falcon," "Greogry Hood and Charlie Wild" and supporting roles in such shows as "Gangbusters," "Counterspy," "Mr. District Attorney," "Theatre Guild on the Air," et al." (www.rainparade.com)','1912-11-16','1997-11-16','https://www.imdb.com/name/nm0677959/','CBSRMT',39) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (40,'jlovejoy','Joan',NULL,'Lovejoy','Joan Lovejoy','Joan Lovejoy maiden name was Banks. She was a voice-over regular on the popular 1930s radio series Gangbusters that featured weekly episodes based actual crime incidents. Each program ended with various descriptions of wanted criminals, many of whom were later arrested due to avid listener participation. She married fellow "Gangbuster" voice-over actor Frank Lovejoy.','1918-10-30','1998-01-18','https://www.imdb.com/name/nm0052180/','CBSRMT',40) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (41,'wgriffis','William',NULL,'Griffis','William Griffis',NULL,'1917-07-12','1998-04-13',NULL,'CBSRMT',41) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (42,'emarshall','E.','G.','Marshall','E. G. Marshall','E.G (Everett) Marshall was the host/narrator for most of the run of CBSRMT.<br> "Marshall made his New York debut in Prologue to Glory (1938) and went on to understudy for the lead in the debut of Eugene O''Neill''s The Iceman Cometh. His film career took off with his role in Twelve Angry Men (1957)."','1910-06-18','1998-08-24',NULL,'CBSRMT',42) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (43,'hhatfield','Hurd',NULL,'Hatfield','Hurd Hatfield','William Rukard Hurd Hatfield was an American leading man best known for his portrayal of the title character in the Oscar-winning 1945 film ''The Picture of Dorian Gray''. A native of New York, Hatfield came to England to study acting at the Chekhov Theatre Studio in Devonshire. He had lived in Ireland since the early 1970''s. Despite numerous roles in scores of other movies, television and stage productions, he was forever associated with his staring role in the film of the Oscar Wilde''s novel.','1917-12-07','1998-12-26',NULL,'CBSRMT',43) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (44,'rkiley','Richard',NULL,'Kiley','Richard Kiley','Won a Tony for "Man Of La Mancha" and "Redhead".','1922-03-31','1999-03-05',NULL,'CBSRMT',44) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (45,'sschnabel','Stefan',NULL,'Schnabel','Stefan Schnabel','In 1938, Schnabel moved to New York and acted in thousands of radio programs. He served in the U.S. Army, then resumed his acting career. Schnabel appeared in theater productions of Around the World in 80 Days, Love of Four Colonels, and Social Security, along with numerous other productions. Schnabel married Marion Kohler and together they founded the Rainbow Theater in Norwalk, Connecticut. Schnabel played Dr. Stephen Jackson on the CBS daytime drama Guiding Light from 1965-81.','1912-02-02','1999-03-11',NULL,'CBSRMT',45) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (46,'ncoleman','Nancy',NULL,'Coleman','Nancy Coleman',NULL,'1912-12-30','2000-01-18',NULL,'CBSRMT',46) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (47,'bstraight','Beatrice',NULL,'Straight','Beatrice Straight','In her long career, Beatrice Straight actually did very little work in the movies, plying her trade mostly on stage. But, when she did grace the silver screen, she did it with great skill. Her first love was theatre, having debuted on Broadway in the','1914-08-02','2001-04-07',NULL,'CBSRMT',47) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (48,'amanson','Alan',NULL,'Manson','Alan Manson','Alan Manson was one of a group of World War II soldiers selected to appear in Irving Berlin''s 1942 musical _This is the Army (1943)_ . He appeared in the Broadway production as well as in the film. After the war he continued to perform on Broadway. In 1955 he was called before the House committee investigating communists in New York theater. He refused to answer any questions but was later cleared. He found little work as an actor for a few years after.','1918-06-07','2002-03-05',NULL,'CBSRMT',48) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (49,'rcrenna','Richard',NULL,'Crenna','Richard Crenna','Was born into a modest income family. His mother managed a small hotel in downtown Los Angeles where Richard and his family resided. He first appeared on network radio while still a teenager as Ougy Pringle in a "Date with Judy" (1946). When that sh','1926-11-30','2003-01-17',NULL,'CBSRMT',49) ON CONFLICT (person_id) DO NOTHING;
