INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (73,'hbrown','Himan',NULL,'Brown','Himan Brown','The famous squeaking door intro to RMT is a continuation of the creaking door found in an earlier series: Inner Sanctum.  Himan Brown was the force behind that series, too.<br>HB also played bit parts in some of the shows. <P> "Himan Brown produced and directed radio series for CBS and NBC during the 1930s and 1940s (The Thin Man, Flash Gordon, Inner Sanctum , and others).  His collection of radio transcription discs includes not only programs he produced or directed, but also others produced for CBS Radio. Titles in the collection include episodes from You Are There (also known as CBS Is There), Suspense, Mystery Theatre, CBS Radio Workshop, Backstage Wife, Mr. Chameleon,  Inspector Brooks, Young Widder Brown, Stella Dallas, and Inspector Hawkes and Son."',NULL,NULL,NULL,'CBSRMT',73) ON CONFLICT (person_id) DO NOTHING;
