INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (120,'adabney','Augusta',NULL,'Dabney','Augusta Dabney','AD studied at the UC Berkeley Department of Theater starred in many radio and TV soap operas.  She also appears on broadway.  She was married to <a href=http://www.mousetrap.net/~mouse/cbsrmt/showperson.php?id=wprince>William Prince</a> and <a href=http://www.mousetrap.net/~mouse/cbsrmt/showperson.php?id=kmccarthy>Kevin McCarthy</a>,  presumably not at the same time.','1918-10-23',NULL,NULL,'CBSRMT',120) ON CONFLICT (person_id) DO NOTHING;
