INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (123,'jorbach','Jerry',NULL,'Orbach','Jerry Orbach','Jerry was born in the Bronx. His father, Leon, was a former vaudevillian actor and his mother, Emily, was a radio singer. His family moved frequently and eventually settled in Waukegan, Illinois where he went to high school. The constant moving made him the new kid on the block and forced him to become "a chameleon" to blend in his new settings. He studied drama at the University of Illinois and at Northwestern. He then went to study acting in New York and got constant work in musicals. He slowly pushed to get acting roles in tv and movies, but was frequently overlooked because of his musical roots.','1935-10-20',NULL,NULL,'CBSRMT',123) ON CONFLICT (person_id) DO NOTHING;
