INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (153,'rrice','Rosemary',NULL,'Rice','Rosemary Rice','In addition to her success on television as Katrin on the popular MAMA series in the 1950s, Rosemary Rice was a busy radio actress during the 1940s and 1950s and was heard on such radio programs as Studio One, Archie Andrews (as Betty), The Cavalcade Of America and When A Girl Marries, to mention just a few. Rice had numerous successful children''s recordings to her credit.',NULL,NULL,NULL,'CBSRMT',153) ON CONFLICT (person_id) DO NOTHING;
