INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (168,'mfairchild','Morgan',NULL,'Fairchild','Morgan Fairchild','In 1973, Morgan decided to pursue a career in television; just 6 weeks after moving to New York she landed the key role of Jennifer in the daytime series "Search for Tomorrow" (1951); she stayed on until 1977.   Morgan moved to Los Angeles, where in 1978 she originated the role of Jenna Wade on the wildly popular nighttime soap "Dallas" (1978)(Jenna was later portrayed by Priscilla Presley). Morgan made numerous guest appearances on TV series. She landed the key role of Constance Semple in "Flamingo Road" (1981) in 1981, and she was nominated for a Golden Globe for Best Actress; that was her breakout show that propelled her to stardom.','1950-02-03',NULL,NULL,'CBSRMT',168) ON CONFLICT (person_id) DO NOTHING;
