INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (190,'bpeters','Brock',NULL,'Peters','Brock Peters','Born of African and West Indian parentage in New York City, Brock Peters set his sights on a show business career early on, at age ten. A product of NYC''s famed Music and Arts High School, Peters initially fielded more odd jobs than acting jobs as he worked his way up from Harlem poverty. Landing a stage role in "Porgy and Bess" in 1949, he quit physical education studies at CCNY and went on tour with the acclaimed musical. His film debut came in 1954''s "Carmen Jones", but he really began to make a name for himself# --having dropped his real name, George Fisher, in 1953# --in such films as "To Kill a Mockingbird" and "The L-Shaped Room".','1927-07-02',NULL,NULL,'CBSRMT',190) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (191,'fsternhagen','Frances',NULL,'Sternhagen','Frances Sternhagen','Raised in Washington, D.C., Frances Sternhagen taught acting, singing and dancing to school children before first performing herself with the Arena Stage Group. Since that time, she has been seen in numerous Broadway show, has been nominated five times for a Tony Award and received one for "The Good Doctor". Other shows that she has appeared in include "Equus", "On Golden Pond", "Angel" and "You Can''t Take it With You". Ms. Sternhagen''s film debut was in Up the Down Staircase (1967). Since then her credits have included Fedora (1978), Starting Over (1979), Outland (1981) and Communion (1989). She delighted Off-Broadway audiences for over two years with her feisty portrayal of the title character in "Driving Miss Daisy".','1930-01-13',NULL,NULL,'CBSRMT',191) ON CONFLICT (person_id) DO NOTHING;
INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (192,'tgrimes','Tammy',NULL,'Grimes','Tammy Grimes','Tammy Grimes was a regular actor on RMT, and narrated the later shows when E.G. Marshall''s health started to fail.  She also played roles on Broadway, including leading roles in Unsinkable Molly Brown and 42nd Street. <P>Triivia: TG is Amanda Plummer''s mother (Amanda was named after a character TG played onstage)!   More trivia: TG was offered the lead role in the TV show Bewitched but turned it down.','1934-01-30',NULL,NULL,'CBSRMT',192) ON CONFLICT (person_id) DO NOTHING;
