INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (207,'jlithgow','John',NULL,'Lithgow','John Lithgow','If born to the theater" has meaning in determining a person''s life path, then John Lithgow is a prime example of this truth. Son of a retired actress and a father who was both a theatrical producer and director, he moved frequently as a child while his father founded and managed local and college theaters and Shakespeare festivals throughout the midwest of the United States. Not until he was 16, and his father became head of the McCarter Theater in Princeton New Jersey, did the family settle down. But for John, the theater was still not a career. He won a scholarship to Harvard University, where he finally caught the acting bug (as well as found a wife). Harvard was followed by a Fullbright scholarship to study at the London Academy of Music and Dramatic Art."','1945-10-19',NULL,NULL,'CBSRMT',207) ON CONFLICT (person_id) DO NOTHING;
