INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (217,'mseldes','Marian',NULL,'Seldes','Marian Seldes','From 1967 to 1991 was a faculty member of the Juilliard School of Drama, where her students included Kevin Kline, Patti LuPone, Kevin Spacey, and Laura Linney.  Earned a 1967 Tony award as Best Featured Actress in Edward Albee''s A Delicate Balance", and has since appeared in Albee''s "Three Tall Women" and "The Play About the Baby".  Earned Tony nominations for "Father''s Day" in 1971, "Deathtrap" in 1978, and "Ring Round the Moon" in 1999.  Entered into the Guinness Book of World Records for appearing in "Deathtrap" from 1978 until late in 1982 without ever missing a single performance. " (IMDB).  She also has written an important book on stage acting.','1928-08-23',NULL,NULL,'CBSRMT',217) ON CONFLICT (person_id) DO NOTHING;
