INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (229,'astang','Arnold',NULL,'Stang','Arnold Stang','Small, slight, bespectacled with horn-rimmed glasses, bulgy eyes and a voice that was a sort of high-pitched nasally, gargly yodel, he was cast most often as impish, nerdy types... He is probably best remembered as the spokesman for Chunky candy bars in a series of very successful commercials in which he exclaimed in his yodelly voice, What a chunk of chocolate!"','1905-04-08',NULL,NULL,'CBSRMT',229) ON CONFLICT (person_id) DO NOTHING;
