INSERT INTO person(person_id,slug,first_name,middle_name,last_name,display_name,bio,birth_date,death_date,imdb_url,legacy_system,legacy_person_id) VALUES (322,'jbeck','Jackson',NULL,'Beck','Jackson Beck','Among his other accomplishments, this man is famous (but perhaps unknown by name) for that wonderfully modulated voice of his with which he so dramatically introduced the ''Superman'' episodes on radio and TV during the 1940''s and 50''s. JB''s personal quotes: "Faster than a speeding bullet...more powerful than a locomotive... able to leap tall buildings in a single bound.... Look! Up in the sky! Is it a bird? Is it a plane? It''s SUPERMAN!"','1912-07-23',NULL,NULL,'CBSRMT',322) ON CONFLICT (person_id) DO NOTHING;
